entries[215133] = { ["name"] = "Binding of Binding", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+9,112 Stamina\n+ 2,450 Random Stat 1\n+ 2,450 Random Stat 2\nUse: Sever your bond at the cost of 1 Blasphemite. (2 Min Cooldown)\nEquip: Your spells and abilities have a chance to empower each unique gem color of an ally's socketed gems. This boon grants ( 1564 / 4) to each empowered secondary stat for 15 sec. This effect will always target your bonded ally, if able.\nSell Price:" }
entries[215134] = { ["name"] = "Fractured Gemstone Locket", ["text"] = "Binds when picked up\nNeck\n+9,112 Stamina\n+ 2,450 Random Stat 1\n+ 2,450 Random Stat 2\nEquip: When you enter combat, gain 1 Dormant Gemstone per socketed gem.\n\nWhenever you heal an ally, bestow upon them 1 Empowered Gemstone to increase the potency of one of their socketed gems by 141 for 20 sec. When their gemstone becomes dormant, it is returned to you.\nSell Price:" }
