entries[215145] = { ["name"] = "Remembrance Stone", ["text"] = "Toy\nUse: Offer a fallen player a respectful burial. (5 Min Cooldown)\n\"Always come prepared.\"\nSell Price:" }
entries[215147] = { ["name"] = "Beautification Iris", ["text"] = "Toy\nUse: Focus a colored beam of light through a gemstone toward a helpless critter. (10 Min Cooldown)\n\"The world is cruel. It does not have to be ugly.\"\nSell Price:" }
entries[215158] = { ["name"] = "Freydrin's Shillelagh", ["text"] = "Quest Item\nUse: Unleash Freya's life magic upon the wilds. (6 Sec Cooldown)\nRequires level 70 to 73 ( 73)\n\"An otherworldly life energy resonates through the wood.\"" }
entries[215159] = { ["name"] = "Pillaged Trophy", ["text"] = "Quest Item\nUnique (6)\n<Right Click to Read>" }
entries[215160] = { ["name"] = "The Big Dig Rig", ["text"] = "Binds when picked up\n\"The only crate sturdy enough to survive Doomshadow. Contains many rare artifacts and supplies.\"\n<Right Click to Open>" }
entries[215164] = { ["name"] = "Broodmother's Egg", ["text"] = "Quest Item\n\"It feels heavier than the usual grub egg.\"" }
entries[215169] = { ["name"] = "Everburning Lantern", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Intellect]\nEquip: Your harmful ranged spells and abilities have a high chance to rouse the lantern's flame, granting a stack of Lamp Light up to 15 times.\n\nAfter 30 sec of collecting stacks, Lamp Light is consumed to attract an equal amount of Fireflies to charge the next target you attack exploding for ( 1 * 151 ) Fire damage per Firefly.\nSell Price:" }
entries[215170] = { ["name"] = "Abyssal Trap", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Strength]\nUse: Place an abyssal trap at your feet. When an enemy comes within 3 yards, a giant water bubble is created for 10 sec. All enemies within the bubble take ( 1 * 195 ) Frost damage every second.\n\nThe trap will exist for 1 min before being automatically disarmed. (1 Min Cooldown)\nSell Price:" }
entries[215171] = { ["name"] = "Fungal Friend Flute", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 Intellect\nEquip: Spells and abilities have a chance to unearth a Colourful Fungal Friend to heal allies for 4513 , grant you 439 mana, or deal ( 1028 * 3) Nature damage over 3 sec to a nearby enemy. (1s cooldown)\n\"Fungal Friends never truly die. Instead their spores seep back into the earth, birthing the Friend anew.\"\nSell Price:" }
entries[215172] = { ["name"] = "Silken Chain Weaver", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Strength]\nUse: Unfurl a myriad of grasping webs in front of you entangling your enemies, reducing damage they deal to you by 30% up to 5255 total damage and reducing their Attack Speed by 15% for 15 sec.\n\n[Attack Speed reduction is less effective against enemies above level 80.] (1 Min Cooldown)\nSell Price:" }
entries[215173] = { ["name"] = "Serum of Unconstrained Senses", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 48 Dodge\n+ 48 Parry\nEquip: Systematically consume a small dosage of the serum when entering combat heightening your senses to their limit.\nIn this state parrying and dodging have a chance to cause you to reposte with a Counter dealing Y Physical damage to your assailant.\n\"Side effects may include loss of balance, vomiting, extreme pain, short term memory loss, long term memory loss, loss of motor functions, hallucinations, and an insatiable appetite for small insects.\"\nSell Price:" }
entries[215174] = { ["name"] = "Concoction: Kiss of Death", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Strength or Intellect]\nUse: Drink from the vial and let the toxins course through your veins increasing all secondary stats by 106 for 30 sec.\n\nJump to administer yourself the antidote to end the effect.\n\nIf the Antidote is not administered before the end of the effect you will be stunned for 5 sec. (2 Min, 30 Sec Cooldown)\n\"WARNING: Failure to administer the antidote shortly after consumption may result in death.\"\nSell Price:" }
entries[215175] = { ["name"] = "Belt of Vials", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Intellect]\nSell Price:" }
entries[215176] = { ["name"] = "Ensemble: Breezebinder's Vestments", ["text"] = "Binds when picked up\nUnique\nUse: Collect the appearances of this armor set.\n\nAppearances only usable by Mages, Priests, and Warlocks." }
entries[215177] = { ["name"] = "Power Cell", ["text"] = "Quest Item\n\"The cell's gold trimming has rusted away, but the dusty cell thrums ever so faintly in your hands. Perhaps it still contains a bit of power.\"" }
entries[215178] = { ["name"] = "Shadow-Binding Ritual Knife", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 96 Mastery\nEquip: Engrave a ritual seal into your skin binding you to the shadows, granting yourself 73 Primary Stat.\n\nYour spells and abilities have a low chance to reduce one of your secondary stats by 265 for 10 sec during combat.\nSell Price:" }
